CREATE FUNCTION audit_test.confirm_upload_private(p_evidence uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e audit_test.evidence; actor audit_test.members; stored_size bigint; BEGIN SELECT * INTO e FROM audit_test.evidence WHERE id=p_evidence; SELECT * INTO actor FROM audit_test.members WHERE workspace_id=e.workspace_id AND user_id=(SELECT auth.uid()) AND active AND role IN ('Owner','Auditor'); IF actor.user_id IS NULL THEN RAISE EXCEPTION 'Audit writer membership required' USING ERRCODE='42501'; END IF; SELECT (metadata->>'size')::bigint INTO stored_size FROM storage.objects WHERE bucket_id='audit-test-evidence' AND name=e.object_key; IF stored_size IS NULL OR stored_size<>e.byte_size THEN RAISE EXCEPTION 'Storage receipt unavailable or size mismatch'; END IF; INSERT INTO audit_test.activity(workspace_id,subject_id,action,actor_id,actor_name,actor_email) VALUES(e.workspace_id,e.id,'Evidence storage receipt verified; quarantined',actor.user_id,actor.display_name,actor.email); RETURN true; END $$; REVOKE ALL ON FUNCTION audit_test.confirm_upload_private(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION audit_test.confirm_upload_private(uuid) TO authenticated; CREATE FUNCTION public.audit_test_confirm_upload(p_evidence uuid) RETURNS boolean LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT audit_test.confirm_upload_private(p_evidence) $$; REVOKE ALL ON FUNCTION public.audit_test_confirm_upload(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.audit_test_confirm_upload(uuid) TO authenticated;
